let sectionIdCounter = 0;

export default class CollapsibleSection extends LightningElement {
    isExpanded = false;
    bodyId;

    constructor() {
        super();
        sectionIdCounter++;
        this.bodyId = `collapsible-section-body-${sectionIdCounter}`;
