        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    public class Service implements Trigger_Action__e {

        public void beforeInsert() {
            Set<Id> accountIds = new Set<Id>();
            for (Contact c : Trigger.new) {
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }

            Map<Id, Account> acctMap = new Map<Id, Account>();
            if (!accountIds.isEmpty()) {
                acctMap = [
                    SELECT Id, BillingStreet, BillingCity, BillingPostalCode, BillingCountry, AccountSource
                    FROM Account
                    WHERE Id IN :accountIds
                ];
            }

            TA_Contact_Queries.getInstance().accountsById = acctMap;
        }
    }
}
