public class OPP_MajorGiftFollowUp_TDTM extends NPE01_TriggerHandler {

    private static final String CLOSED_WON = 'Closed Won';
    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;

    public override Boolean handleInsert(List<SObject> newRecords) {
        List<Task> tasks = new List<Task>();
        for (SObject sObj : newRecords) {
            Opportunity opp = (Opportunity) sObj;
            if (opp.StageName == CLOSED_WON && opp.Amount != null && opp.Amount >= MAJOR_GIFT_THRESHOLD) {
                tasks.add(buildTask(opp));
            }
        }
        if (!tasks.isEmpty()) {
            Insert tasks;
        }
        return true;
    }

    public override Boolean handleUpdate(List<SObject> newRecords, Map<Id, SObject> oldRecords) {
        List<Task> tasks = new List<Task>();
        for (SObject sObj : newRecords) {
            Opportunity opp = (Opportunity) sObj;
            if (opp.StageName == CLOSED_WON && opp.Amount != null && opp.Amount >= MAJOR_GIFT_THRESHOLD) {
                Opportunity old = (Opportunity) oldRecords.get(opp.Id);
                Boolean wasQualified = old != null 
                    && old.StageName == CLOSED_WON 
                    && old.Amount != null 
                    && old.Amount >= MAJOR_GIFT_THRESHOLD;
                if (!wasQualified) {
                    tasks.add(buildTask(opp));
                }
            }
        }
        if (!tasks.isEmpty()) {
            Insert tasks;
        }
        return true;
    }

    private Task buildTask(Opportunity opp) {
        Task t = new Task();
        t.Subject = 'Major gift thank-you call';
        t.Priority = 'High';
        t.Status = 'Not Started';
        t.WhatId = opp.Id;
        t.WhoId = opp.npsp__Primary_Contact__c;
        t.OwnerId = opp.OwnerId;
        if (opp.CloseDate != null) {
            t.ActivityDate = opp.CloseDate.addDays(3);
        }
        return t;
    }
}
